import os


class Config:
    """
    Central configuration for the Notebook Cell Ordering pipeline.
    Implements settings for Idea 9: Multi-View Stacked Ranking with Latent Semantic Anchoring.
    """

    # --------------------------------------------------------------------------
    # File System Paths
    # --------------------------------------------------------------------------
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"
    # Working directory for caching intermediate files (parquet/joblib)
    WORKING_DIR = "./working/idea_9"

    # Metadata Files (Generated by previous steps)
    TRAIN_METADATA_PATH = os.path.join(METADATA_DIR, "train_metadata.csv")
    VAL_METADATA_PATH = os.path.join(METADATA_DIR, "val_metadata.csv")
    TEST_METADATA_PATH = os.path.join(METADATA_DIR, "test_metadata.csv")

    # Output Paths
    SUBMISSION_DIR = "./submission"
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # --------------------------------------------------------------------------
    # Reproducibility & Runtime
    # --------------------------------------------------------------------------
    RANDOM_SEED = 42
    NUM_WORKERS = 4

    # Debugging / Development
    # Set to True to process a small subset of data for rapid iteration
    DEBUG = False
    DEBUG_SAMPLE_SIZE = 2000

    # --------------------------------------------------------------------------
    # Feature Engineering Hyperparameters
    # --------------------------------------------------------------------------

    # TF-IDF Vectorization (Stage 1 & Anchors)
    # Configuration based on Lesson 00004, 00005, and Idea 9
    TFIDF_PARAMS = {
        "input": "content",
        "encoding": "utf-8",
        "decode_error": "replace",
        "strip_accents": None,  # Explicitly defined as None
        "lowercase": True,
        "analyzer": "word",
        "stop_words": "english",
        "token_pattern": r"(?u)\b\w\w+\b",
        "ngram_range": (1, 2),  # Unigrams + Bigrams
        "max_features": 60000,  # Vocabulary size
        "norm": "l2",
        "use_idf": True,
        "smooth_idf": True,
        "sublinear_tf": True,  # Logarithmic term frequency
    }

    # Latent Semantic Analysis (SVD)
    # Configuration based on Lesson 00011 and Idea 9
    SVD_N_COMPONENTS = 128
    SVD_RANDOM_STATE = RANDOM_SEED

    # --------------------------------------------------------------------------
    # Model Hyperparameters
    # --------------------------------------------------------------------------

    # Stage 1: Ridge Regression (The "Signpost" Model)
    # Used for high-bias baseline prediction
    N_FOLDS = 5
    RIDGE_PARAMS = {
        "alpha": 1.0,
        "solver": "auto",
        "random_state": RANDOM_SEED,
    }

    # Stage 2: LightGBM Regressor (The "Refinement" Model)
    # Minimizes Mean Absolute Error (MAE)
    LGBM_PARAMS = {
        "objective": "regression_l1",  # Minimize MAE
        "metric": "mae",
        "boosting_type": "gbdt",
        "learning_rate": 0.05,
        "num_leaves": 63,
        "feature_fraction": 0.8,
        "bagging_fraction": 0.8,
        "bagging_freq": 5,
        "verbosity": -1,  # Silent
        "n_jobs": -1,
        "random_state": RANDOM_SEED,
        "n_estimators": 5000,  # High cap, controlled by early stopping
    }

    # Training Loop Settings
    LGBM_EARLY_STOPPING_ROUNDS = 100
    LGBM_VERBOSE_EVAL = 100

    @classmethod
    def setup(cls):
        """
        Creates necessary directories for working files and submissions.
        Should be called at the start of the pipeline.
        """
        os.makedirs(cls.WORKING_DIR, exist_ok=True)
        os.makedirs(cls.SUBMISSION_DIR, exist_ok=True)
